 return <section className="shared-access" aria-label="Shared plan access"><div><LockKeyhole size={20}/><strong>{viewing?'You have viewing access':'Join to edit with your friends'}</strong><p>{viewing?'You can explore the schedule, map and activity details.':collab.signedIn?'Choose the name your friends will see.':'Sign in to keep your edits and approvals attached to your own identity.'}</p></div>{!viewing&&state.people&&(!collab.signedIn?<a className="btn primary" target="_top" href={`/signin-with-chatgpt?return_to=${encodeURIComponent('/#trip='+shareToken())}`}>Sign in with ChatGPT</a>:collab.canJoin?<form onSubmit={e=>{e.preventDefault();void onJoin(name);}}><input aria-label="Your name for this plan" value={name} maxLength={60} onChange={e=>setName(e.target.value)}/><button className="btn primary" disabled={busy||!name.trim()}>Join plan</button></form>:<span>Ask the owner for editing access.</span>)}</section>;
