  <div className="trip-card-actions"><button className="btn small-btn" disabled={busy} onClick={onOpen}>Open plan</button><button className="icon-button" disabled={busy} aria-label={`Delete ${trip.plan.name}`} onClick={onDelete}><Trash2 size={17}/></button></div>
