    <div className="item-bottom"><span>{i.price===null?'Cost unknown':i.price===0?'Free / included':<><strong>{dollars(i.shares[actor]??0)}</strong> your share</>}</span><span>{i.booking==='failed'?<Pill tone="red">Booking failed</Pill>:i.paid.length>0&&i.price?`${i.paid.length}/${i.participants.length} shares paid`:'View details'}</span></div>
